-- Session migration, Phase 2 increment 14.
-- Authored from prisma/schema.prisma in this increment, because the
-- Prisma engine download fails in this workspace and no local Prisma
-- run can generate it. This file is NOT claimed as generated by a
-- local Prisma run. Its proof is the GitHub Actions workflow in
-- .github/workflows/prisma-migration.yml, which runs prisma migrate
-- deploy with the committed migrations against an ephemeral Postgres
-- 15 service container, plus the new workflow in
-- .github/workflows/prisma-session-validate.yml, which runs prisma
-- validate and prisma generate against the schema including the new
-- Session model. Both workflows are pushed, and neither run is
-- claimed as passed here, because this environment cannot check a
-- run status on GitHub. Do NOT edit the already applied migration
-- in prisma/migrations/20261105000000_init/. This migration adds
-- one table only, Session, for server side sessions. It stores a
-- hash of the session token only, never the plain token. Sessions
-- are deleted with their user (cascade). This migration has NOT
-- been applied to the live Neon database in this increment. The
-- live Neon database still needs the owner to run the manual
-- Neon migrate deploy workflow on GitHub once, after this push,
-- exactly as for the initial migration. No prices, trial values,
-- or limits are hard coded here. Sample data: none.

CREATE TABLE "Session" (
    "id" TEXT NOT NULL DEFAULT gen_random_uuid(),
    "userId" TEXT NOT NULL,
    "tokenHash" TEXT NOT NULL,
    "expiresAt" TIMESTAMP(3) NOT NULL,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "Session_pkey" PRIMARY KEY ("id")
);
CREATE UNIQUE INDEX "Session_tokenHash_key" ON "Session"("tokenHash");
CREATE INDEX "Session_userId_idx" ON "Session"("userId");
ALTER TABLE "Session" ADD CONSTRAINT "Session_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
